package com.hailbell

import java.util.Locale

/**
 * The chat's own words in the user's language (their locale's language when it is covered, otherwise
 * English). The same 14 languages as the iOS SDK and the web widget.
 */
internal object L10n {
    val language: String by lazy {
        val code = Locale.getDefault().language.lowercase()
        if (table.containsKey(code)) code else "en"
    }

    fun text(key: String, vars: Map<String, String> = emptyMap()): String {
        var s = table[language]?.get(key) ?: table["en"]?.get(key) ?: key
        for ((k, v) in vars) s = s.replace("{$k}", v)
        return s
    }

